// Ivory espresso cutout generated for the wallet reward artwork.
// Source asset: public/img/reward-cup.png. No network or native canvas needed in Workers.
export const CUP_WIDTH = 389;
export const CUP_HEIGHT = 300;
const DATA = '';
let pixels;
export function cupPixels() {
  return pixels ||= (async () => {
    const bytes = Uint8Array.from(atob(DATA), c => c.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate'));
    return new Uint8Array(await new Response(stream).arrayBuffer());
  })();
}
